import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { setLocalData } from '../utils/storage';

function Login() {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  // Tài khoản mẫu để test
  const fakeAccounts = [
    { username: 'admin', password: '123456', name: 'Nguyễn Văn Admin', role: 'admin' },
    { username: 'nhanvien', password: '123456', name: 'Trần Thị Nhân Viên', role: 'employee' },
  ];

  function handleLogin(e) {
    e.preventDefault();
    const found = fakeAccounts.find(
      (acc) => acc.username === username && acc.password === password
    );
    if (found) {
      setLocalData('currentUser', found);
      navigate('/dashboard');
    } else {
      setError('Tên đăng nhập hoặc mật khẩu không đúng.');
    }
  }

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#f1f3f5',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}>
      <div style={{
        backgroundColor: '#fff',
        padding: '32px',
        borderRadius: '8px',
        border: '1px solid #ddd',
        width: '360px'
      }}>
        <h4 style={{ textAlign: 'center', marginBottom: '8px', color: '#2563eb' }}>
          HRM System
        </h4>
        <p style={{ textAlign: 'center', color: '#888', fontSize: '13px', marginBottom: '24px' }}>
          Hệ thống quản lý nhân sự
        </p>

        {error && (
          <div style={{
            backgroundColor: '#fef2f2',
            border: '1px solid #fca5a5',
            color: '#dc2626',
            padding: '8px 12px',
            borderRadius: '4px',
            fontSize: '13px',
            marginBottom: '16px'
          }}>
            {error}
          </div>
        )}

        <form onSubmit={handleLogin}>
          <div style={{ marginBottom: '14px' }}>
            <label style={{ display: 'block', fontSize: '13px', marginBottom: '4px', color: '#444' }}>
              Tên đăng nhập
            </label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Nhập tên đăng nhập"
              style={{
                width: '100%',
                padding: '8px 10px',
                border: '1px solid #ccc',
                borderRadius: '4px',
                fontSize: '14px',
                boxSizing: 'border-box'
              }}
            />
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', fontSize: '13px', marginBottom: '4px', color: '#444' }}>
              Mật khẩu
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Nhập mật khẩu"
              style={{
                width: '100%',
                padding: '8px 10px',
                border: '1px solid #ccc',
                borderRadius: '4px',
                fontSize: '14px',
                boxSizing: 'border-box'
              }}
            />
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              padding: '10px',
              backgroundColor: '#2563eb',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              fontSize: '14px',
              cursor: 'pointer'
            }}
          >
            Đăng nhập
          </button>
        </form>

        <p style={{ marginTop: '16px', fontSize: '12px', color: '#aaa', textAlign: 'center' }}>
          Tài khoản test: admin / 123456
        </p>
      </div>
    </div>
  );
}

export default Login;
